mapper.select:
SELECT * FROM gym_holiday
WHERE YEAR(holiday_date) = #{year} AND gym_id = #{gymId}
ORDER BY holiday_date ASC

mapper.insert:
INSERT INTO gym_holiday (gym_id, holiday_date, type, name)
VALUES (#{gymId}, #{holiday.holidayDate}, #{holiday.type}, #{holiday.name})
ON DUPLICATE KEY UPDATE name = #{holiday.name}
